// the golden tests assert each whole generated file as one inline snapshot, so their bodies are long
/* oxlint-disable max-lines-per-function */
import { expect, mock, onTestFinished, test } from 'bun:test';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { writeRestoreJobs } from './write-restore-jobs.ts';

async function setupTest() {
  const root = await mkdtemp(join(tmpdir(), 'write-restore-jobs-'));

  onTestFinished(() => rm(root, { recursive: true, force: true }));

  // the directories that hold the stack config and the two restore Jobs, which every checkout has
  await mkdir(join(root, 'infra'));
  await mkdir(join(root, 'images', 'atc-gateway'), { recursive: true });
  await mkdir(join(root, 'deploy', 'nixie'), { recursive: true });

  const printOut = mock<(text: string) => void>();
  const printErr = mock<(text: string) => void>();

  return { root, printOut, printErr };
}

test("it writes the gateway's restore Job from its backup pod and the stack's backup image", async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  const status = await writeRestoreJobs({
    args: [ctx.root],
    printOut: ctx.printOut,
    printErr: ctx.printErr,
  });

  const written = await readFile(
    join(ctx.root, 'images', 'atc-gateway', 'restore-job.yaml'),
    'utf8',
  );

  expect(status).toBe(0);

  expect(written).toMatchInlineSnapshot(`
      "# Generated by \`bun run write:restore-job\` from the backup pod in
      # infra/cluster/build-atc-gateway-backup-pod-spec.ts and the stack config's atcGateway.backupImage: never
      # edit it by hand. \`bun run check:restore-job\` fails when it differs.
      #
      # One-off restore of the atc gateway's state. Stop the gateway first
      # (docs/runbooks/atc-gateway-backup-restore.md), then:
      #   ssh root@geoffcloud k3s kubectl create -f - < images/atc-gateway/restore-job.yaml
      # To list the snapshots instead, set args to ['ls']; to restore another snapshot, set SNAPSHOT.
      apiVersion: batch/v1
      kind: Job
      metadata:
        generateName: atc-gateway-restore-
        namespace: atc
      spec:
        backoffLimit: 0
        ttlSecondsAfterFinished: 86400
        template:
          spec:
            restartPolicy: Never
            securityContext:
              runAsNonRoot: true
              runAsUser: 65532
              runAsGroup: 65532
              fsGroup: 65532
              seccompProfile:
                type: RuntimeDefault
            automountServiceAccountToken: false
            imagePullSecrets:
              - name: ghcr-pull
            containers:
              - name: restore
                image: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb
                args:
                  - restore
                env:
                  - name: STATE_DIR
                    value: /state
                  - name: HOME
                    value: /tmp
                  - name: SNAPSHOT
                    value: latest
                envFrom:
                  - secretRef:
                      name: atc-gateway-backup
                volumeMounts:
                  - name: state
                    mountPath: /state
                  - name: tmp
                    mountPath: /tmp
                securityContext:
                  allowPrivilegeEscalation: false
                  capabilities:
                    drop:
                      - ALL
            volumes:
              - name: state
                persistentVolumeClaim:
                  claimName: atc-gateway-state
              - name: tmp
                emptyDir: {}
      "
    `);
});

test("it writes nixie's restore Job from its backup pod and the stack's backup image", async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  await writeRestoreJobs({ args: [ctx.root], printOut: ctx.printOut, printErr: ctx.printErr });

  const written = await readFile(join(ctx.root, 'deploy', 'nixie', 'restore-job.yaml'), 'utf8');

  expect(written).toMatchInlineSnapshot(`
    "# Generated by \`bun run write:restore-job\` from the backup pod in
    # infra/cluster/build-nixie-backup-pod-spec.ts and the stack config's atcGateway.backupImage: never
    # edit it by hand. \`bun run check:restore-job\` fails when it differs.
    #
    # One-off restore of nixie.db and keys.db, from the nixie-backup CronJob's repository. Stop nixie
    # first (docs/runbooks/nixie.md), then:
    #   ssh root@geoffcloud k3s kubectl create -f - < deploy/nixie/restore-job.yaml
    # To list the snapshots instead, set args to ['ls']; to restore another snapshot, set SNAPSHOT. The
    # claim is data-nixie-0, nixie's own; the restore test swaps in its scratch claim,
    # nixie-restore-check (docs/runbooks/nixie-backup.md). The script and the Secret come from the
    # CronJob's fixed-name ConfigMap and Secret.
    apiVersion: batch/v1
    kind: Job
    metadata:
      generateName: nixie-restore-
      namespace: nixie
    spec:
      backoffLimit: 0
      ttlSecondsAfterFinished: 86400
      template:
        spec:
          restartPolicy: Never
          securityContext:
            runAsNonRoot: true
            runAsUser: 10001
            runAsGroup: 10001
            fsGroup: 10001
            seccompProfile:
              type: RuntimeDefault
          automountServiceAccountToken: false
          imagePullSecrets:
            - name: ghcr-pull
          containers:
            - name: restore
              image: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb
              command:
                - /bin/sh
                - /opt/nixie-backup/backup.sh
              args:
                - restore
              env:
                - name: STATE_DIR
                  value: /state
                - name: HOME
                  value: /tmp
                - name: SNAPSHOT
                  value: latest
              envFrom:
                - secretRef:
                    name: nixie-backup
              volumeMounts:
                - name: state
                  mountPath: /state
                - name: script
                  mountPath: /opt/nixie-backup
                  readOnly: true
                - name: tmp
                  mountPath: /tmp
              securityContext:
                allowPrivilegeEscalation: false
                capabilities:
                  drop:
                    - ALL
          volumes:
            - name: state
              persistentVolumeClaim:
                claimName: data-nixie-0
            - name: script
              configMap:
                name: nixie-backup-script
            - name: tmp
              emptyDir: {}
    "
  `);
});

test('it names each file it writes', async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  await writeRestoreJobs({ args: [ctx.root], printOut: ctx.printOut, printErr: ctx.printErr });

  expect(ctx.printOut.mock.calls).toStrictEqual([
    ['write-restore-jobs: wrote images/atc-gateway/restore-job.yaml\n'],
    ['write-restore-jobs: wrote deploy/nixie/restore-job.yaml\n'],
  ]);
});

test('it passes the check and writes nothing when both files match their builders', async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  await writeRestoreJobs({
    args: [ctx.root],
    printOut: mock<(text: string) => void>(),
    printErr: mock<(text: string) => void>(),
  });

  const status = await writeRestoreJobs({
    args: ['--check', ctx.root],
    printOut: ctx.printOut,
    printErr: ctx.printErr,
  });

  expect(status).toBe(0);
  expect(ctx.printOut).not.toHaveBeenCalled();
  expect(ctx.printErr).not.toHaveBeenCalled();
});

test("it fails the check, naming the file, when one field of the YAML differs from its builder's output", async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  await writeRestoreJobs({
    args: [ctx.root],
    printOut: mock<(text: string) => void>(),
    printErr: mock<(text: string) => void>(),
  });

  const path = join(ctx.root, 'images', 'atc-gateway', 'restore-job.yaml');

  const generated = await readFile(path, 'utf8');

  await writeFile(path, generated.replace('backoffLimit: 0', 'backoffLimit: 3'));

  const status = await writeRestoreJobs({
    args: ['--check', ctx.root],
    printOut: ctx.printOut,
    printErr: ctx.printErr,
  });

  expect(status).toBe(1);

  expect(ctx.printErr.mock.calls).toStrictEqual([
    [
      "write-restore-jobs: images/atc-gateway/restore-job.yaml differs from its builder's output; run bun run write:restore-job\n",
    ],
  ]);
});

test('it leaves a differing file as it is under the check', async () => {
  const ctx = await setupTest();

  await writeFile(
    join(ctx.root, 'infra', 'Pulumi.prod.yaml'),
    `config:
  geoff-cloud:atcGateway:
    image: ghcr.io/zgeoff/atc-gateway:9.1.0@sha256:${'a'.repeat(64)}
    backupImage: ghcr.io/zgeoff/atc-gateway-backup:9.0.0-r3@sha256:${'b'.repeat(64)}
    publicURL: https://gateway.example.org
    daemons:
      lighthouse:
        address: 100.64.0.7:8415
        daemonID: 3f2b1c4d-5e6f-4a7b-8c9d-0e1f2a3b4c5d
    defaultDaemon: lighthouse
`,
  );

  await writeFile(
    join(ctx.root, 'images', 'atc-gateway', 'restore-job.yaml'),
    'kind: Job\nmetadata:\n  name: by-hand\n',
  );

  await writeRestoreJobs({
    args: ['--check', ctx.root],
    printOut: ctx.printOut,
    printErr: ctx.printErr,
  });

  const kept = await readFile(join(ctx.root, 'images', 'atc-gateway', 'restore-job.yaml'), 'utf8');

  expect(kept).toBe('kind: Job\nmetadata:\n  name: by-hand\n');
});

